origin.script:
'use strict';

export function init(value) {
	shared.particles = thisScene.createLayer('particles/sparks.json') !== null;
	shared.sound = thisScene.createLayer({ sound: ['sounds/tone.wav'], name: 'Made sound', startsilent: true }) !== null;
	return value;
}

'use strict';

let frames = 0;

export function update(value) {
	frames += 1;
	const tone = thisScene.getLayer('Tone');
	if (frames === 3) tone.stop();
	shared.frames = frames;
	return value;
}

